    // ========== TÉCNICAS AVANÇADAS ==========

    private async Task AbrirDetalhesTecnica(TecnicaAvancadaModel tecnica)
    {
        var options = new DialogOptions { CloseOnEscapeKey = true, MaxWidth = MaxWidth.Small, FullWidth = true };
        var parameters = new DialogParameters<MensagemCustomizada> { { x => x.Titulo, tecnica.Nome }, { x => x.Conteudo, tecnica.Explicacao } };
        await DialogService.ShowAsync<MensagemCustomizada>("Detalhes da Técnica", parameters, options);
    }

    private async Task AbrirExemploTecnica(TecnicaAvancadaModel tecnica)
    {
        var options = new DialogOptions { CloseOnEscapeKey = true, MaxWidth = MaxWidth.Small, FullWidth = true };
        var sb = new System.Text.StringBuilder();
        sb.Append("<div class='mud-table mud-simple-table mud-table-bordered mud-table-striped mud-elevation-1 mt-2'><div class='mud-table-container'><table class='mud-table-root'><thead class='mud-table-head' style='background-color: rgba(255,107,53,0.1);'><tr class='mud-table-row'><th class='mud-table-cell' style='color:coral; font-weight:bold;'>Passo</th><th class='mud-table-cell' style='color:coral; font-weight:bold;'>Ação</th><th class='mud-table-cell' style='color:coral; font-weight:bold;'>Detalhe</th></tr></thead><tbody class='mud-table-body'>");
        foreach (var p in tecnica.PassosPraticos)
            sb.Append($"<tr class='mud-table-row'><td class='mud-table-cell'><b>{p.Passo}</b></td><td class='mud-table-cell'>{p.Acao}</td><td class='mud-table-cell'>{p.Detalhe}</td></tr>");
        sb.Append("</tbody></table></div></div>");
        var p2 = new DialogParameters<MensagemCustomizada> { { x => x.Titulo, $"Como Aplicar: {tecnica.Nome}" }, { x => x.Conteudo, sb.ToString() } };
        await DialogService.ShowAsync<MensagemCustomizada>("Exemplo Prático", p2, options);
    }

    public class TecnicaAvancadaModel
    {
        public string Nome { get; set; } = "";
        public string Tagline { get; set; } = "";
        public string Descricao { get; set; } = "";
        public string Nivel { get; set; } = "";
        public string QuandoUsar { get; set; } = "";
        public string Icone { get; set; } = "";
        public bool Inverter { get; set; }
        public string CardGradient { get; set; } = "";
        public List<string> Beneficios { get; set; } = new();
        public string Explicacao { get; set; } = "";
        public List<PassoPratico> PassosPraticos { get; set; } = new();
    }

    public class PassoPratico
    {
        public string Passo { get; set; } = "";
        public string Acao { get; set; } = "";
        public string Detalhe { get; set; } = "";
    }

