    {
        new TecnicaAvancadaModel { Nome = "Drop Set", Tagline = "Alongue sua série até a falha total", Descricao = "Após atingir a falha com sua carga de trabalho, reduza o peso em 20-30% e continue sem descanso até nova falha. Pode-se fazer uma, duas ou três reduções consecutivas (double/triple drop). Ideal para o final do treino.", Nivel = "Intermediário a Avançado", QuandoUsar = "Final do treino, último exercício", Icone = Icons.Material.Filled.TrendingDown, Inverter = false, CardGradient = "linear-gradient(135deg, #2d1b4e 0%, #1a0d30 100%)", Beneficios = new() { "Leva o músculo à falha absoluta", "Recruta fibras profundas", "Excelente para quebrar platôs", "Aumenta pump e densidade" }, Explicacao = "O Drop Set foi popularizado por Arnold Schwarzenegger e consiste em estender uma série além da falha reduzindo a carga progressivamente. Estudos mostram que essa técnica gera um estresse metabólico extremo, um dos três principais mecanismos de hipertrofia. As fibras de contração rápida (Tipo II) são forçadas a trabalhar mesmo com cargas reduzidas, pois as fibras lentas já estão completamente exauridas. Aplique 1-2 drop sets por grupamento em máquinas, polias ou halteres; evite exercícios com barra livre onde a falha pode comprometer a segurança.", PassosPraticos = new() { new() { Passo = "1", Acao = "Série Base", Detalhe = "Faça 8-12 reps até a falha com sua carga normal" }, new() { Passo = "2", Acao = "1ª Queda", Detalhe = "Reduza 20-30% do peso e continue sem descanso até nova falha" }, new() { Passo = "3", Acao = "2ª Queda", Detalhe = "Reduza mais 20-30% e vá até a falha absoluta (opcional)" }, new() { Passo = "4", Acao = "Descanso", Detalhe = "Descanse 2-3 min antes de repetir (máx. 1-2 drop sets)" } } },
